<script setup lang="ts">
import {computed,ref,onMounted} from 'vue'
import {save} from '@tauri-apps/plugin-dialog'
import {command,message,desktop} from '../api'
import {date,localDate,number} from '../format'
import PageHeading from '../components/PageHeading.vue'
const to=ref(localDate()),from=ref(localDate().slice(0,4)+'-01-01'),busy=ref(false),error=ref(''),success=ref('')
const stats=ref<{summary:{studies:number;patients:number};byType:{name:string;count:number}[];byDoctor:{name:string;count:number}[];byMonth:{name:string;count:number}[]}>()
const applied=ref<{from:string;to:string}>(),exporting=ref(false)
const periodChanged=computed(()=>!applied.value||applied.value.from!==from.value||applied.value.to!==to.value)
let request=0
async function load(){const ticket=++request,period={from:from.value,to:to.value};busy.value=true;error.value='';success.value='';stats.value=undefined;applied.value=undefined;try{const result=await command<NonNullable<typeof stats.value>>('statistics',period);if(ticket===request){stats.value=result;applied.value=period}}catch(e){if(ticket===request)error.value=message(e)}finally{if(ticket===request)busy.value=false}}
async function exportCsv(){if(!desktop||!stats.value||!applied.value||periodChanged.value||busy.value||exporting.value)return;const period={...applied.value};exporting.value=true;error.value='';success.value='';try{const path=await save({defaultPath:`Статистика-${period.from}-${period.to}.csv`,filters:[{name:'CSV',extensions:['csv']}]});if(path){await command('export_statistics',{path,...period});success.value='Отчёт сохранён'}}catch(e){error.value=message(e)}finally{exporting.value=false}}

onMounted(load)
</script>
<template><section class="page-content"><PageHeading title="Статистика" description="Завершённые исследования за выбранный период"><UButton icon="i-lucide-download" variant="outline" :disabled="!desktop||!stats||busy||periodChanged||exporting" :loading="exporting" @click="exportCsv">Сохранить CSV</UButton></PageHeading><form @submit.prevent="load" class="date-filter"><UFormField label="С"><UInput v-model="from" type="date" required/></UFormField><UFormField label="По"><UInput v-model="to" type="date" required/></UFormField><UButton type="submit" :loading="busy">Показать</UButton></form><UAlert v-if="error" color="error" variant="soft" :description="error" class="mb-5"/><UAlert v-if="success" color="success" variant="soft" :description="success" class="mb-5"/><p v-if="stats&&periodChanged" class="text-slate-600 mb-5 no-print">Период изменён. Нажмите «Показать», чтобы обновить отчёт и разрешить выгрузку.</p><template v-if="stats"><p v-if="applied" class="text-slate-600 mb-3">Отчёт за {{date(applied.from)}} — {{date(applied.to)}}</p><p class="statistics-summary">{{number(stats.summary.studies)}} исследований · {{number(stats.summary.patients)}} пациентов</p><p class="text-slate-600 mb-7">Черновики, удалённые в исходной программе записи и записи без пациента в отчёт не входят.</p><section v-for="(rows,key) in {byType:stats.byType,byDoctor:stats.byDoctor,byMonth:stats.byMonth}" :key="key" class="settings-section"><h2 class="mb-5">{{key==='byType'?'По видам исследований':key==='byDoctor'?'По врачам':'По месяцам'}}</h2><div class="table-scroll"><table class="patient-table"><thead><tr><th>{{key==='byMonth'?'Месяц':'Наименование'}}</th><th class="text-right">Исследований</th></tr></thead><tbody><tr v-for="row in rows" :key="row.name"><td>{{row.name}}</td><td class="text-right tabular-nums">{{number(row.count)}}</td></tr><tr v-if="!rows.length"><td colspan="2">За этот период данных нет</td></tr></tbody></table></div></section></template></section></template>
